Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{

    if (view.Host is not Orc.Cards.Card self || view.Card is not Orc.Cards.Card played) { return; }
    if (!object.ReferenceEquals(played, self)) { return; }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    var random = Orc.Game.MatchRandomService.ResolveFor(self);
    var engine = ctx.Engine;
    if (runtime is null || random is null || engine is null) { return; }

    Func<Orc.Cards.Card, Orc.Game.Players.Player?> ownerOf = c =>
    {
        if (c is Orc.Game.Players.Hq hq) { return hq.Owner; }
        if (c is Orc.Game.Cards.CardBase cb) { return cb.Owner; }
        return null;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onField = u =>
        u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) && !st.IsDestroyed && st.Line is not null;

    Func<Orc.Game.Cards.UnitCard, bool> isInfantry = u =>
    {
        foreach (var t in u.Definition.UnitTypes)
        {
            if (string.Equals(t, "infantry", System.StringComparison.OrdinalIgnoreCase)) { return true; }
        }
        return false;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onFrontLine = u =>
    {
        if (!u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) || st.IsDestroyed || st.Line is null)
        {
            return false;
        }
        return st.Line.Name.Contains("前线", System.StringComparison.Ordinal);
    };

    var owner = ownerOf(self);
    if (owner is null) { return; }

    var enemyIndex = 1 - owner.Index;

    // 本回合监听：友方单位部署/加入 -> 随机 1 个敌方目标 1 点伤害；回合结束自注销。
    System.IDisposable? subscription = null;
    subscription = engine.Subscribe(async (kind, payload, token) =>
    {
        if (string.Equals(kind, Orc.Game.GameUpdates.TurnEnd, System.StringComparison.Ordinal))
        {
            if (subscription is not null) { subscription.Dispose(); }
            return;
        }

        if (!string.Equals(kind, Orc.Game.GameUpdates.UnitDeployed, System.StringComparison.Ordinal)
            && !string.Equals(kind, Orc.Game.GameUpdates.UnitJoined, System.StringComparison.Ordinal))
        {
            return;
        }

        if (payload is null
            || !payload.TryGetValue(Orc.Game.GameUpdates.PayloadUnit, out var raw)
            || raw is not Orc.Game.Cards.UnitCard deployed
            || !object.ReferenceEquals(deployed.Owner, owner))
        {
            return;
        }

        var targets = new System.Collections.Generic.List<Orc.Cards.Card>();
        foreach (var c in engine.Cards)
        {
            if (c is Orc.Game.Players.Hq hq)
            {
                if (hq.Owner.Index == enemyIndex) { targets.Add(hq); }
            }
            else if (c is Orc.Game.Cards.UnitCard u
                && !object.ReferenceEquals(u.Owner, owner)
                && onField(u))
            {
                targets.Add(u);
            }
        }

        if (targets.Count == 0) { return; }
        var pick = random.PickOne(targets);
        await runtime.DamageAsync(pick, 1, self, token);
    });
};
